import cv2, glob, numpy as np

frames = sorted(glob.glob('/root/keyframes_*.png'))

def prep_edge(img):
    return cv2.Canny(img, 50, 150)

def count_matches(img, templ, thresh):
    res = cv2.matchTemplate(img, templ, cv2.TM_CCOEFF_NORMED)
    yxs = np.where(res >= thresh)
    if len(yxs[0]) == 0:
        return 0
    scores = res[yxs]
    idxs = np.argsort(scores)[::-1]
    h, w = templ.shape[:2]
    accepted = []
    for idx in idxs:
        y = int(yxs[0][idx])
        x = int(yxs[1][idx])
        cx, cy = x + w/2, y + h/2
        too_close = False
        for ax, ay in accepted:
            if abs(cx - ax) < w*0.6 and abs(cy - ay) < h*0.6:
                too_close = True
                break
        if not too_close:
            accepted.append((cx, cy))
    return len(accepted)

coin = prep_edge(cv2.imread('/root/coin.png', cv2.IMREAD_GRAYSCALE))
enemy = prep_edge(cv2.imread('/root/enemy.png', cv2.IMREAD_GRAYSCALE))
turtle = prep_edge(cv2.imread('/root/turtle.png', cv2.IMREAD_GRAYSCALE))

templates = [('coin',coin),('enemy',enemy),('turtle',turtle)]
thresholds = [0.3,0.4,0.5,0.6,0.7,0.8]

for name, templ in templates:
    print('\n', name)
    for thresh in thresholds:
        counts = []
        for path in frames:
            img = prep_edge(cv2.imread(path, cv2.IMREAD_GRAYSCALE))
            counts.append(count_matches(img, templ, thresh))
        print(thresh, counts)
